-- Exact-catalogue batch: Suzuki, Yamaha and Kawasaki factory heritage
-- Captures private editorial draft notes ONLY. No published research.
-- Atomic gate: any ID change, alias review or prior staging aborts entire batch.
DO $$
DECLARE matched integer; inserted integer; before_published integer; after_published integer;
BEGIN
 SELECT count(*) INTO before_published FROM public.motorcycle_universal_published_sections_v1;
 WITH expected(id,make,model) AS (VALUES
 (644,'Suzuki','GSX-R750'),
(232,'Suzuki','GSX-R1000'),
(648,'Suzuki','SV650'),
(650,'Suzuki','V-Strom 650'),
(719,'Yamaha','YZF-R1'),
(701,'Yamaha','FJR1300'),
(889,'Kawasaki','GPZ900R')
 )
 SELECT count(*) INTO matched FROM expected e
 JOIN public.motorcycle_catalog_models m ON m.id=e.id AND m.manufacturer=e.make AND m.model=e.model
 WHERE NOT EXISTS (SELECT 1 FROM public.motorcycle_universal_page_sections_v1 s WHERE s.entity_type='model' AND s.model_id=e.id)
 AND NOT EXISTS (SELECT 1 FROM public.motorcycle_catalog_model_aliases a WHERE a.alias_model_id=e.id AND a.review_status<>'approved');
 IF matched<>7 THEN RAISE EXCEPTION 'Motorcycle source capture aborted: expected seven exact unstaged identities, got %',matched; END IF;
 INSERT INTO public.motorcycle_universal_page_sections_v1
 (entity_type,manufacturer_id,model_id,section_number,section_title,content,editorial_status,source_reference,published_at)
 SELECT 'model',NULL,v.model_id,v.section_number,v.section_title,v.content,'draft','factory_heritage_research:'||v.source_url,NULL
 FROM (VALUES (644,1,'Model introduction','{"summary":"The GSX-R750 brought Suzuki endurance-racing ideas to a road-going, fully faired sports motorcycle.","source_name":"Suzuki factory heritage","source_url":"https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/sports_081.php","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original summary captured from manufacturer archive; claims, exact market/year and photo licensing require independent review before release."}'::jsonb,'https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/sports_081.php'),
(644,7,'Documented model history','{"summary":"Suzuki records the original GSX-R750''s appearance at the 1984 Cologne motorcycle show and its 1985 launch in Japan.","source_name":"Suzuki factory heritage","source_url":"https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/sports_081.php","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original summary captured from manufacturer archive; claims, exact market/year and photo licensing require independent review before release."}'::jsonb,'https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/sports_081.php'),
(644,12,'Original-generation engineering','{"summary":"Suzuki''s archive documents a four-valve DOHC engine with the SACS oil-cooling system in the first GSX-R750; later generations require separate specifications.","source_name":"Suzuki factory heritage","source_url":"https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/sports_081.php","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original summary captured from manufacturer archive; claims, exact market/year and photo licensing require independent review before release."}'::jsonb,'https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/sports_081.php'),
(232,1,'Model introduction','{"summary":"The GSX-R1000 continued Suzuki''s lightweight GSX-R superbike approach in the litre-class road sport segment.","source_name":"Suzuki factory heritage","source_url":"https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/sports_080.php","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original summary captured from manufacturer archive; claims, exact market/year and photo licensing require independent review before release."}'::jsonb,'https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/sports_080.php'),
(232,7,'Documented model history','{"summary":"Suzuki''s factory archive identifies the original GSX-R1000 as a 2001 motorcycle derived from the GSX-R750 platform.","source_name":"Suzuki factory heritage","source_url":"https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/sports_080.php","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original summary captured from manufacturer archive; claims, exact market/year and photo licensing require independent review before release."}'::jsonb,'https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/sports_080.php'),
(232,12,'Original-generation engineering','{"summary":"For the 2001 GSX-R1000, Suzuki documents a liquid-cooled inline-four, a twin-spar frame and fuel injection; year-specific changes must remain separate.","source_name":"Suzuki factory heritage","source_url":"https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/sports_080.php","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original summary captured from manufacturer archive; claims, exact market/year and photo licensing require independent review before release."}'::jsonb,'https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/sports_080.php'),
(648,1,'Model introduction','{"summary":"The SV650 arrived as a middleweight roadster built around a 90-degree V-twin, balancing urban manoeuvrability and touring use.","source_name":"Suzuki factory heritage","source_url":"https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/ss4_045.php","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original summary captured from manufacturer archive; claims, exact market/year and photo licensing require independent review before release."}'::jsonb,'https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/ss4_045.php'),
(648,7,'Documented model history','{"summary":"Suzuki documents the SV650 and separately styled SV650S in 1999, with a substantially revised generation arriving in 2003.","source_name":"Suzuki factory heritage","source_url":"https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/ss4_045.php","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original summary captured from manufacturer archive; claims, exact market/year and photo licensing require independent review before release."}'::jsonb,'https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/ss4_045.php'),
(648,12,'Original-generation engineering','{"summary":"Suzuki records a 645 cc liquid-cooled DOHC V-twin and aluminium truss frame for its original 1999 SV650. Later specifications differ.","source_name":"Suzuki factory heritage","source_url":"https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/ss4_045.php","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original summary captured from manufacturer archive; claims, exact market/year and photo licensing require independent review before release."}'::jsonb,'https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/ss4_045.php'),
(650,1,'Model introduction','{"summary":"The V-Strom 650 was conceived as a middleweight sport-adventure tourer with rider comfort, luggage provision and road versatility in mind.","source_name":"Suzuki factory heritage","source_url":"https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/dual_109.php","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original summary captured from manufacturer archive; claims, exact market/year and photo licensing require independent review before release."}'::jsonb,'https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/dual_109.php'),
(650,7,'Documented model history','{"summary":"Suzuki''s factory model archive distinguishes the 2004 V-Strom 650 from the updated 2013 and 2017 generations.","source_name":"Suzuki factory heritage","source_url":"https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/dual_109.php","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original summary captured from manufacturer archive; claims, exact market/year and photo licensing require independent review before release."}'::jsonb,'https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/dual_109.php'),
(650,12,'Original-generation engineering','{"summary":"The 2004 Suzuki V-Strom 650 used a 645 cc V-twin, aluminium twin-beam frame, adjustable windscreen and 22-litre fuel tank.","source_name":"Suzuki factory heritage","source_url":"https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/dual_109.php","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original summary captured from manufacturer archive; claims, exact market/year and photo licensing require independent review before release."}'::jsonb,'https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/dual_109.php'),
(719,1,'Model introduction','{"summary":"Yamaha''s YZF-R1 reshaped the late-1990s litre-class sportbike with compact packaging and responsive road performance.","source_name":"Yamaha factory heritage","source_url":"https://global.yamaha-motor.com/showroom/cp/collection/yzf-r1/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original summary captured from manufacturer archive; claims, exact market/year and photo licensing require independent review before release."}'::jsonb,'https://global.yamaha-motor.com/showroom/cp/collection/yzf-r1/'),
(719,7,'Documented model history','{"summary":"Yamaha''s Communication Plaza identifies the original YZF-R1 as a production motorcycle from 1998.","source_name":"Yamaha factory heritage","source_url":"https://global.yamaha-motor.com/showroom/cp/collection/yzf-r1/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original summary captured from manufacturer archive; claims, exact market/year and photo licensing require independent review before release."}'::jsonb,'https://global.yamaha-motor.com/showroom/cp/collection/yzf-r1/'),
(719,12,'Original-generation engineering','{"summary":"The 1998 Yamaha YZF-R1 employed a liquid-cooled 998 cc five-valve inline-four and Deltabox II chassis. These are original-generation details only.","source_name":"Yamaha factory heritage","source_url":"https://global.yamaha-motor.com/showroom/cp/collection/yzf-r1/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original summary captured from manufacturer archive; claims, exact market/year and photo licensing require independent review before release."}'::jsonb,'https://global.yamaha-motor.com/showroom/cp/collection/yzf-r1/'),
(701,1,'Model introduction','{"summary":"Yamaha developed the FJR1300 as a large-capacity sport-tourer for long-distance road travel and passenger comfort.","source_name":"Yamaha factory heritage","source_url":"https://global.yamaha-motor.com/showroom/cp/collection/fjr1300as/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original summary captured from manufacturer archive; claims, exact market/year and photo licensing require independent review before release."}'::jsonb,'https://global.yamaha-motor.com/showroom/cp/collection/fjr1300as/'),
(701,7,'Documented model history','{"summary":"Yamaha''s heritage notes the FJR1300 introduction in 2001 and an FJR1300AS high-end variant in 2006. Variant-only features must not be assigned to all FJR1300s.","source_name":"Yamaha factory heritage","source_url":"https://global.yamaha-motor.com/showroom/cp/collection/fjr1300as/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original summary captured from manufacturer archive; claims, exact market/year and photo licensing require independent review before release."}'::jsonb,'https://global.yamaha-motor.com/showroom/cp/collection/fjr1300as/'),
(889,1,'Model introduction','{"summary":"Kawasaki''s GPz900R became an early landmark of the Ninja sportbike family, combining road-focused performance with aerodynamic bodywork.","source_name":"Kawasaki factory heritage","source_url":"https://global.kawasaki.com/en/corp/profile/division/motorcycle_engine/history.html","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original summary captured from manufacturer archive; claims, exact market/year and photo licensing require independent review before release."}'::jsonb,'https://global.kawasaki.com/en/corp/profile/division/motorcycle_engine/history.html'),
(889,7,'Documented model history','{"summary":"Kawasaki''s official corporate chronology records the GPz900R motorcycle''s introduction in 1984, a milestone in its Ninja history.","source_name":"Kawasaki factory heritage","source_url":"https://global.kawasaki.com/en/corp/profile/division/motorcycle_engine/history.html","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original summary captured from manufacturer archive; claims, exact market/year and photo licensing require independent review before release."}'::jsonb,'https://global.kawasaki.com/en/corp/profile/division/motorcycle_engine/history.html')) AS v(model_id,section_number,section_title,content,source_url);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>19 THEN RAISE EXCEPTION 'Expected 19 draft research sections, inserted %',inserted; END IF;
 SELECT count(*) INTO after_published FROM public.motorcycle_universal_published_sections_v1;
 IF before_published<>after_published THEN RAISE EXCEPTION 'Public universal section count changed unexpectedly'; END IF;
END $$;
